using System;using System.IO;using System.Linq;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using DashCanvas;
class DecorationTests {
 static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;}
 static string Hash(Bitmap b){using(var sha=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(Pictures.Png(b)));}
 static int Main(string[] args){try{string output=args.Length>0?Path.GetFullPath(args[0]):Path.GetFullPath("test-results");Directory.CreateDirectory(output);
 string[] styles=new[]{"Plain","Neon","Double Neon","Antique Gold","Carved Wood","Ornate Corners","Scrollwork"}.Concat(Decoration.ExtraFrames).ToArray();
 using(var sample=new Bitmap(180,140))using(var shape=new Bitmap(180,140))using(var sheet=new Bitmap(1080,570)){
 using(var g=Graphics.FromImage(sample)){g.Clear(Color.FromArgb(19,46,75));g.FillEllipse(Brushes.Coral,60,25,60,60);g.FillPolygon(Brushes.Teal,new[]{new Point(20,120),new Point(70,60),new Point(130,120)});}using(var g=Graphics.FromImage(shape)){g.SmoothingMode=SmoothingMode.AntiAlias;g.FillEllipse(Brushes.White,8,8,164,124);}
 using(var sg=Graphics.FromImage(sheet)){sg.Clear(Color.FromArgb(15,21,32));int i=0;var distinct=new System.Collections.Generic.HashSet<string>();foreach(var style in styles){var d=new Design{Shape="Rounded",FrameStyle=style,FrameColor=style=="Carved Wood"?Color.SaddleBrown:style=="Antique Gold"||style=="Ornate Corners"||style=="Scrollwork"?Color.Goldenrod:Color.Cyan,FrameColor2=Color.DeepPink,FrameWidth=5};using(var im=Designer.Render(sample,shape,d)){Check(im.Size==shape.Size,"dimensions: "+style);distinct.Add(Hash(im));sg.DrawImageUnscaled(im,(i%6)*180,(i/6)*190);sg.DrawString(style,SystemFonts.DefaultFont,Brushes.White,(i%6)*180+8,(i/6)*190+150);}i++;}Check(distinct.Count==styles.Length,"every frame style has a distinct appearance");}sheet.Save(Path.Combine(output,"frame-styles.png"));
 foreach(var style in styles)foreach(string pattern in new[]{"Solid","Dashed","Dotted","Dash-dot"}){var d=new Design{Shape="Original shape",FrameStyle=style,LinePattern=pattern,FrameWidth=5,DeletedLayers=new[]{"Image"}};using(var rendered=Designer.Render(sample,shape,d)){bool visible=false;for(int y=0;y<shape.Height;y++)for(int x=0;x<shape.Width;x++){if(shape.GetPixel(x,y).A<=16&&rendered.GetPixel(x,y).A!=0)throw new Exception("frame outside alpha edge: "+style+" / "+pattern);visible|=rendered.GetPixel(x,y).A>0;}Check(visible,"visible frame: "+style+" / "+pattern);}}
 var aligned=new Design{Shape="Rectangle",FrameStyle="Gradient",DeletedLayers=new[]{"Image"}};RectangleF? first=null;foreach(int width in new[]{1,3,8}){aligned.FrameWidth=width;using(var r=Designer.Render(sample,shape,aligned)){var bounds=Decoration.ContentBounds(r);if(first.HasValue)Check(bounds==first.Value,"width preserves outer edge");else first=bounds;}}
 var colors=new Design{Shape="Rectangle",FrameStyle="Gradient",FrameColor=Color.Red,FrameColor2=Color.Blue,GradientAngle=0,DeletedLayers=new[]{"Image"}};using(var r=Designer.Render(sample,shape,colors))Check(r.GetPixel(1,70).R>r.GetPixel(178,70).R&&r.GetPixel(1,70).B<r.GetPixel(178,70).B,"gradient uses both selected colors and angle");
 using(var textSheet=new Bitmap(900,510))using(var g=Graphics.FromImage(textSheet)){g.Clear(Color.FromArgb(15,21,32));int i=0;foreach(string effect in new[]{"Solid","Outline","Shadow","Neon","Gold","Gradient","Double Outline","Emboss","Engraved"}){var d=new Design{Shape="Rectangle",Border=false,Caption="DASH\nSTUDIO",TextSize=70,TextPosition="Center",TextEffect=effect,TextColor=Color.Gold,TextColor2=Color.DeepPink,DeletedLayers=new[]{"Image"}};using(var r=Designer.Render(sample,shape,d)){Check(r.GetPixel(0,0).A==0,"text stays transparent: "+effect);Check(Decoration.ContentBounds(r).Width>30,"text renders: "+effect);g.DrawImage(r,(i%3)*300+60,(i/3)*170,180,140);g.DrawString(effect,SystemFonts.DefaultFont,Brushes.White,(i%3)*300+10,(i/3)*170+145);}i++;}textSheet.Save(Path.Combine(output,"text-styles.png"));}
 var label=new Design{Border=false,Caption="FIRST\nLINE",TextSize=35,DeletedLayers=new[]{"Image"},TextAlign="Left"};using(var left=Designer.Render(sample,shape,label)){label.TextAlign="Right";using(var right=Designer.Render(sample,shape,label))Check(Decoration.ContentBounds(left).Left<Decoration.ContentBounds(right).Left,"multiline alignment changes position");label.TextAlign="Left";label.Underline=true;using(var under=Designer.Render(sample,shape,label))Check(Hash(under)!=Hash(left),"underline changes rendered labels");label.Underline=false;label.StrikeThrough=true;using(var strike=Designer.Render(sample,shape,label))Check(Hash(strike)!=Hash(left),"strikethrough changes rendered labels");}
 }
 foreach(int size in new[]{1,4,16})using(var tiny=new Bitmap(size,size)){using(var g=Graphics.FromImage(tiny))g.Clear(Color.Coral);foreach(var style in styles)using(var r=Designer.Render(tiny,tiny,new Design{Shape="Rectangle",FrameStyle=style}))Check(r.Size==tiny.Size,"tiny textures: "+style);}
 Console.WriteLine("PASS: "+checks+" decoration checks. Synthetic previews: "+output);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
